edits.replacement:
.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1d (his #50, from the AAA judge and the lint of the stash shot): THE STASH KEEPS THE 13 PIXEL FLOOR. The
   stash is drawn at 0.92 of the window size (his v9.67 note: text in the Undercroft only slightly smaller), and its smallest labels
   were set at the 13px floor, so 28 of them painted at 11.9px: the tabs, SORT, STASH and LOADOUT, the counts, the key bar, the hint
   lines, the brand and the version. Those smallest labels are set at 14.2px now, which the 0.92 brings to the 13px floor; every
   larger word keeps his slight reduction. The tabs are 16px, so the stash filters read at a glance. No word changed. */
#root #hub .brand, #root #hub #verlabel, #root #hub #reptop, #root #hub #stashsort, #root #hub .lohead, #root #hub #invcols em,
#root #hub #kitcol em, #root #hub #kitcol b, #root #hub .cell .cnt, #root #hub .loslab, #root #hub #invkeybar kbd, #root #hub #invkeybar div,
#root #hub #stashdetail span, #root #hub #sellhint, #root #hub #firstkit, #root #hub #sellall, #root #hub #stashsearch,
#root #hub #hotplanwrap span, #root #hubfreekit b, #root #hubfreekit span, #root #hub [style*="font-size:13px"]{ font-size:14.2px !important; }
#root #hub #stashtabs .invtab{ font-size:16px !important; }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1d, from the AAA judge and the lint of the stash shot): on the stash, drawn at 0.92 of the window size (his v9.67 note), no label paints under the 13px floor (font size times the zoom), and the stash tabs are 16px',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], hub, z, q, i, el, f, low=[], tab, n=0;
   function zoomOf(e){ var zz=1; for(var p=e;p&&p.nodeType===1;p=p.parentElement){ zz*=(parseFloat(getComputedStyle(p).zoom)||1); } return zz; }
   try{
     __topClear(); __hubEnter(); __station('term','KeyE');
     hub=document.getElementById('hub');
     if(!hub||getComputedStyle(hub).display==='none') return 'SKIP: the stash did not open';
     // the stash zoom against the window factor (0.92 by his v9.67 note), so the headless window size does not move the measure
     z=(parseFloat(getComputedStyle(hub).zoom)||1)/((typeof menuScale==='function'&&menuScale())||1);
     q=hub.querySelectorAll('.brand,#verlabel,#stashsort,.lohead,.loslab,#invkeybar kbd,#sellhint,#stashtabs .invtab,.cell .cnt');
     for(i=0;i<q.length;i++){
       el=q[i]; if(!el.getClientRects().length) continue;
       n++; f=parseFloat(getComputedStyle(el).fontSize)*z;
       if(f<12.95) low.push((el.id||el.className||el.tagName)+' '+f.toFixed(1)+'px');
     }
     if(n<6) bad.push('only '+n+' stash labels were found to measure');
     if(low.length) bad.push(low.length+' stash labels paint under 13px at zoom '+z.toFixed(2)+': '+low.slice(0,5).join(', '));
     tab=hub.querySelector('#stashtabs .invtab');
     if(tab&&parseFloat(getComputedStyle(tab).fontSize)<16) bad.push('a stash tab is '+getComputedStyle(tab).fontSize);
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
